"""
Glossary, Schemas, and Reference Tables Generator for LegalMitra README Part XXIII.
Generates an extensive 100-term Indian Legal Glossary and complete database/schema field dictionaries.
"""

def generate_expanded_legal_glossary() -> str:
    terms = [
        ("Act (अधिनियम)", "A bill passed by both Houses of Parliament or a State Legislative Assembly and assented to by the President or Governor under Article 111 or Article 200 of the Constitution."),
        ("Actionable Claim", "A claim to any debt, other than a debt secured by mortgage of immoveable property or by hypothecation or pledge of moveable property, as defined under Section 3 of the Transfer of Property Act, 1882."),
        ("Adjudicating Authority", "An authority appointed under specialized enactments (such as Section 6 of PMLA, 2002 or IBC, 2016) to adjudicate civil liability, asset confiscation, or insolvency."),
        ("Advance Medical Directive (Living Will)", "A written instrument executed by an adult of sound mind expressing advance directives regarding medical treatment in the event of terminal illness, recognized under *Common Cause v. UOI (2018)*."),
        ("Advocate-on-Record (AoR)", "An advocate entitled under the Supreme Court Rules to act as well as to plead for a party in the Supreme Court of India."),
        ("Affidavit", "A written statement of facts voluntarily made by an affiant under an oath or affirmation administered by a person authorized by law under the Oaths Act, 1969."),
        ("Alibi", "A plea under Section 11 of the Indian Evidence Act, 1872 (now Section 9 BSA, 2023) asserting that the accused was elsewhere at the time of the alleged commission of the offense."),
        ("Amicus Curiae", "Latin for 'friend of the court'; an experienced advocate appointed by the court to assist in a matter involving complex questions of law or public interest."),
        ("Anticipatory Bail", "A pre-arrest direction issued by the High Court or Sessions Court under Section 482 BNSS, 2023 (formerly Section 438 CrPC) directing release on bail in the event of arrest for a non-bailable offense."),
        ("Appellate Tribunal", "A specialized judicial or quasi-judicial body established by statute to hear appeals against decisions of regulatory commissions (e.g., NCLAT, TDSAT, NGT, APTEL)."),
        ("Approver", "An accomplice who is granted a pardon under Section 343 BNSS (formerly Section 306 CrPC) on condition of making a full and true disclosure of the circumstances within his knowledge relating to the offense."),
        ("Arbitral Award", "A final determination on merits made by an arbitral tribunal under Section 31 of the Arbitration and Conciliation Act, 1996, enforceable as a decree of the civil court under Section 36."),
        ("Arrest Memo", "A mandatory document executed at the time of arrest recording the date, time, and location of arrest, signed by at least one witness and countersigned by the arrestee pursuant to *D.K. Basu v. State of West Bengal* and Section 36 BNSS."),
        ("Article 12 State", "The Government and Parliament of India, the Government and Legislature of each State, and all local or other authorities within the territory of India or under the control of the Government of India, subject to Fundamental Rights."),
        ("Article 14 Equality", "The constitutional guarantee under Article 14 that the State shall not deny to any person equality before the law or equal protection of the laws within India, prohibiting arbitrariness (*E.P. Royappa*)."),
        ("Article 21 Life and Liberty", "The fundamental right providing that no person shall be deprived of his life or personal liberty except according to procedure established by law, interpreted in *Maneka Gandhi* to require just, fair, and reasonable procedure."),
        ("Article 32 Constitutional Remedies", "The fundamental right to move the Supreme Court by appropriate proceedings for the enforcement of Part III rights, described by Dr. B.R. Ambedkar as the 'heart and soul' of the Constitution."),
        ("Article 141 Binding Precedent", "The constitutional mandate declaring that the law declared by the Supreme Court shall be binding on all courts within the territory of India."),
        ("Article 142 Complete Justice", "The plenary equitable power of the Supreme Court to pass such decree or make such order as is necessary for doing complete justice in any cause or matter pending before it."),
        ("Article 226 High Court Writs", "The constitutional jurisdiction empowering High Courts to issue writs, directions, or orders to any person or authority for the enforcement of Fundamental Rights and for any other purpose."),
        ("Bailable Offence", "An offense shown as bailable in the First Schedule to the BNSS, 2023, or made bailable by any other law, wherein bail is a matter of statutory right under Section 478 BNSS."),
        ("Bail Bond", "A written undertaking executed by an accused or surety agreeing to pay a specified sum of money if the accused fails to appear before the court or police pursuant to bail terms."),
        ("Basic Structure Doctrine", "The judicial principle established in *Kesavananda Bharati (1973)* limiting the constituent amending power under Article 368 from altering essential democratic, secular, and judicial features."),
        ("Bench Coram", "The composition and count of judges presiding over a judicial proceeding, determining authority hierarchy (e.g., Single Judge < Division Bench (2) < Full Bench (3) < Constitution Bench (5+))."),
        ("Bharatiya Nagarik Suraksha Sanhita (BNSS)", "Central Act No. 46 of 2023 governing criminal procedure, investigations, trial processes, and execution of sentences, replacing the CrPC, 1973 from July 1, 2024."),
        ("Bharatiya Nyaya Sanhita (BNS)", "Central Act No. 45 of 2023 establishing substantive criminal offenses and penalties in the Republic of India, replacing the IPC, 1860 from July 1, 2024."),
        ("Bharatiya Sakshya Adhiniyam (BSA)", "Central Act No. 47 of 2023 establishing the law of evidence, witness examination, and electronic records admissibility, replacing the IEA, 1872 from July 1, 2024."),
        ("Bill of Rights (Part III)", "Articles 12 to 35 of the Constitution of India enshrining fundamental rights enforceable against the State."),
        ("Cause of Action", "The entire bundle of essential facts that the plaintiff must prove in order to support his right to a judgment of the court under Order II Rule 2 of the Code of Civil Procedure, 1908."),
        ("Caveat", "A formal notice lodged under Section 148A of the CPC requesting the court not to pass an ex-parte order without giving notice to the caveator."),
        ("Certiorari", "A prerogative writ issued by superior courts to quash an order passed by an inferior court, tribunal, or quasi-judicial authority in excess of jurisdiction or in violation of natural justice."),
        ("Charge Sheet (Police Report)", "A final report submitted by an investigating police officer under Section 193 BNSS (formerly Section 173(2) CrPC) upon conclusion of investigation finding sufficient evidence against the accused."),
        ("Cheque Dishonour (Section 138 NI Act)", "Statutory criminal offense under Section 138 of the Negotiable Instruments Act, 1881 for dishonour of a cheque due to insufficiency of funds or exceeding arrangements."),
        ("Civil Contempt", "Willful disobedience to any judgment, decree, direction, order, writ, or other process of a court, or willful breach of an undertaking given to a court under Section 2(b) of the Contempt of Courts Act, 1971."),
        ("Cognizable Offence", "An offense for which a police officer may arrest without a warrant and is legally mandated to register an FIR and commence investigation without prior magisterial permission."),
        ("Commercial Dispute", "A dispute arising out of transactions of merchants, bankers, financiers, and traders, including export/import, maritime, intellectual property, and joint ventures under Section 2(1)(c) of the Commercial Courts Act, 2015."),
        ("Compounding of Offences", "A statutory compromise mechanism under Section 359 BNSS (formerly Section 320 CrPC) whereby victim and accused settle an offense without trial, resulting in acquittal."),
        ("Confession", "An admission made at any time by a person charged with a crime, stating or suggesting the inference that he committed that crime, governed by Section 22 to 24 BSA (formerly Section 24-30 IEA)."),
        ("Constitutional Bench", "A bench of not less than five judges of the Supreme Court constituted under Article 145(3) to decide cases involving substantial questions of law as to the interpretation of the Constitution."),
        ("Coram Non Judice", "A proceeding conducted before a court or officer lacking lawful jurisdiction, rendering all resultant orders ab initio void."),
        ("Criminal Contempt", "The publication of any matter or doing of any act which scandalizes, prejudices, or interferes with the due course of judicial proceedings under Section 2(c) of the Contempt of Courts Act, 1971."),
        ("Cross-Examination", "The examination of a witness by the adverse party under Section 142 BSA (formerly Section 137 IEA) to test veracity, impeach credit, and elicit favorable facts."),
        ("Custodial Death", "The demise of an individual while in police or judicial detention, requiring mandatory judicial magisterial inquiry under Section 196 BNSS (formerly Section 176(1A) CrPC)."),
        ("Cy-près Doctrine", "An equitable doctrine applied in trust and charity law providing that when a charitable intention cannot be carried out literally, the court will apply the funds to a purpose as near as possible to the original intention."),
        ("Damnum Sine Injuria", "Latin legal maxim meaning 'damage without legal injury'; actual damage or loss incurred without infringement of a legally protected legal right, creating no cause of action in tort (*Gloucester Grammar School*)."),
        ("Decree", "The formal expression of an adjudication which, so far as regards the court expressing it, conclusively determines the rights of the parties with regard to all or any of the matters in controversy in the suit under Section 2(2) CPC."),
        ("Default Bail (Statutory Bail)", "An absolute statutory right to bail accrued under Section 187(2) BNSS (formerly Section 167(2) CrPC) when the police fail to file a charge sheet within the prescribed 60 or 90 day window."),
        ("Delegated Legislation", "Rules, regulations, statutory orders, and bylaws enacted by executive departments pursuant to legislative authority conferred by an Act of Parliament or State Legislature."),
        ("De Minimis Non Curat Lex", "Latin maxim meaning 'the law does not concern itself with trifles', codified in Section 25 of the Bharatiya Nyaya Sanhita, 2023 (formerly Section 95 IPC)."),
        ("Devanagari Script", "The Indic alphasyllabary script specified in Article 343(1) of the Constitution for official Hindi language records and statutory enactments."),
        ("Discovery under Evidence Law", "Fact-finding mechanism under Section 23 BSA (formerly Section 27 IEA) admitting information leading to the recovery of a distinct physical object discovered in consequence of information received from an accused in custody."),
        ("Dying Declaration", "A statement made by a person as to the cause of his death or circumstances of the transaction resulting in death, admissible under Section 26(a) BSA (formerly Section 32(1) IEA)."),
        ("Electronic Record", "Data, record, or data generated, image or sound stored, received or sent in an electronic form under Section 2(1)(t) of the Information Technology Act, 2000, authenticated via Section 63 BSA."),
        ("Eminent Domain", "The inherent power of the sovereign state to acquire private property for public use upon payment of just compensation, regulated by the RFCTLARR Act, 2013 and Article 300A."),
        ("Ex-Parte Order", "An order or decree passed by a judicial authority in the absence of one of the parties, subject to application for setting aside under Order IX Rule 13 CPC."),
        ("First Information Report (FIR)", "The earliest information recorded under Section 173 BNSS (formerly Section 154 CrPC) regarding the commission of a cognizable offense, triggering the investigative machinery."),
        ("Golden Triangle", "The constitutional synthesis of Articles 14, 19, and 21 established in *Maneka Gandhi (1978)*, mandating that any law curtailing liberty must satisfy the tests of equality, freedom, and fairness simultaneously."),
        ("Habeas Corpus", "A high prerogative constitutional writ commanding the person or authority detaining another to produce the body of the prisoner before the court to test the legality of detention."),
        ("Hearing on Sentence", "A mandatory post-conviction procedural stage under Section 258(2) BNSS (formerly Section 235(2) CrPC) where the convict is heard on mitigating and aggravating factors prior to sentence determination."),
        ("High Court Neutral Citation", "Standardized uniform citation format adopted by Indian High Courts (e.g., `2024:DHC:1420` for Delhi High Court) enabling open-access case identification."),
        ("Hostile Witness", "A witness who exhibits hostility to the party calling him, permitting the party to cross-examine their own witness with the permission of the court under Section 157 BSA (formerly Section 154 IEA)."),
        ("IBM Docling", "An open-source deep learning document layout analysis and PDF extraction engine integrated into LegalMitra for structural gazette conversion."),
        ("In Limine", "Latin for 'at the threshold'; disposal or dismissal of a petition at the preliminary stage without entering into a full hearing on merits."),
        ("Inherent Powers", "Uncodified statutory powers preserved in superior courts under Section 528 BNSS (formerly Section 482 CrPC) and Section 151 CPC to make orders necessary to prevent abuse of process."),
        ("Injunction", "A judicial process whereby a party is required to do, or to refrain from doing, any particular act, governed by Sections 36 to 42 of the Specific Relief Act, 1963 and Order XXXIX CPC."),
        ("Interlocutory Application (IA)", "An application filed in a pending suit or proceeding seeking interim relief or procedural directions prior to final decree."),
        ("Judicial Review", "The constitutional power of superior courts under Articles 32, 136, 226, and 227 to examine the legislative competence and constitutional validity of statutes and executive actions."),
        ("Jus Tertii", "The right of a third party; a defense raised in property actions asserting that a third person has a superior title to the plaintiff."),
        ("Juvenile Justice Board (JJB)", "A specialized judicial body constituted under Section 4 of the Juvenile Justice Act, 2015 to deal with children in conflict with law."),
        ("Kesavananda Bharati Ruling", "Historic Thirteen-Judge Bench judgment (1973) 4 SCC 225 establishing the Basic Structure Doctrine and sovereign limits on constitutional amendments."),
        ("Leading Question", "Any question suggesting the answer which the person putting it wishes or expects to receive, regulated under Sections 146-148 BSA (formerly Sections 141-143 IEA)."),
        ("Legal Legal Diff", "A computational algorithm that compares provisions of amending legislation against parent statutes to identify modifications (substitutions, insertions, omissions, repeals)."),
        ("Letters Patent Appeal (LPA)", "An intra-court appeal to a Division Bench against the judgment of a Single Judge of a Chartered High Court pursuant to its original Letters Patent."),
        ("Lex Loci", "The law of the place where an act occurred, a contract was made, or property is situated."),
        ("Limitation Period", "The statutory timeframe prescribed under the Limitation Act, 1963 beyond which legal proceedings cannot be instituted or are barred by time."),
        ("Locus Standi", "The legal capacity or entitlement of a party to bring an action or be heard before a court of law, substantially relaxed in public interest litigation (PIL)."),
        ("Mandamus", "A prerogative writ issued to a public official, tribunal, or statutory body commanding the performance of a public duty mandated by law."),
        ("Maneka Gandhi Precedent", "Landmark Supreme Court judgment (1978) 1 SCC 248 holding that procedure established by law under Article 21 must be just, fair, and reasonable, incorporating substantive due process principles."),
        ("Mens Rea", "The blameworthy mental state or criminal intention accompanying an unlawful physical act (actus reus), essential for criminal liability unless expressly excluded by statute."),
        ("Mesne Profits", "Profits which the person in wrongful possession of property actually received, or might with ordinary diligence have received, together with interest, defined under Section 2(12) CPC."),
        ("Natural Justice (Audi Alteram Partem & Nemo Judex)", "Fundamental procedural fairness rules requiring: (1) no person shall be condemned unheard; and (2) no person shall be a judge in their own cause."),
        ("Negative Constraint Checking", "An algorithmic validation gate in LegalMitra verifying that generated answers do not contain prohibited terms, repealed provisions, or legally invalid propositions."),
        ("Non-Bailable Offence", "An offense where bail cannot be claimed as a matter of right, resting within the judicial discretion of the court under Section 480 BNSS (formerly Section 437 CrPC)."),
        ("Non-Retroactivity (Article 20(1))", "Constitutional prohibition against ex-post facto criminal laws: no person shall be convicted of any offense except for violation of law in force at the time of commission."),
        ("Noscitur a Sociis", "Canon of statutory interpretation meaning 'the meaning of a doubtful word may be ascertained by reference to the meaning of words associated with it'."),
        ("Obiter Dicta", "Observations or opinions expressed by a court upon some matter not essential to the determination of the legal issue, lacking binding precedent force."),
        ("Official Gazette (Rajpatra)", "The official public record published by the Central or State Government providing authoritative notice of statutory enactments, commencement orders, and notifications."),
        ("Original Jurisdiction", "The authority of a court to hear and determine a case in the first instance, as exercised by the Supreme Court under Article 131 for federal inter-state disputes."),
        ("Pari Materia", "Statutes in pari materia are those relating to the same person, thing, or subject matter; construed together as forming one statutory system."),
        ("Per Incuriam", "A judicial decision rendered in ignorance or forgetfulness of a binding statutory provision or a decision of a superior court, depriving it of precedent authority."),
        ("Pleadings", "Formal written statements filed in a civil proceeding: the plaint filed by the plaintiff and the written statement filed by the defendant under Orders VI, VII, and VIII CPC."),
        ("POCSO Act", "The Protection of Children from Sexual Offences Act, 2012, mandating in-camera trials, child-friendly procedures, and strict identity confidentiality under Section 33(7)."),
        ("Precedent", "A judicial decision that establishes a rule or principle of law serving as an authoritative guide for subsequent decisions in similar cases under Article 141."),
        ("Preventive Detention", "The detention of a person without trial to prevent them from committing acts prejudicial to state security, defense, or public order under Article 22 and enactments like PSA or NSA."),
        ("Proviso", "A statutory clause beginning with 'Provided that', qualifying, restricting, or creating an exception to the enacting section."),
        ("Public Interest Litigation (PIL)", "A judicial mechanism under Article 32 or 226 initiated by any public-spirited individual to enforce rights on behalf of disadvantaged persons or public causes."),
        ("Quantum Meruit", "Latin for 'as much as he has deserved'; legal claim for reasonable compensation for services performed where no specific contract price was stipulated."),
        ("Quashment", "The judicial nullification or setting aside of an FIR, complaint, or criminal proceeding under Section 528 BNSS (formerly Section 482 CrPC) or Article 226."),
        ("Quo Warranto", "A prerogative writ issued to challenge the legality of a person's claim to occupy a public substantive office."),
        ("Ratio Decidendi", "The legal principle, reason, or rationale forming the core basis of a judicial decision, carrying binding precedent force under Article 141."),
        ("Res Judicata", "Section 11 CPC doctrine barring parties from re-litigating a matter directly and substantially in issue that has been conclusively decided by a competent court in a former suit."),
        ("Restitution", "The act of restoring a party to the position they would have occupied but for an erroneous decree or judgment, codified under Section 144 CPC."),
        ("Revision", "The supervisory jurisdiction of High Courts and Sessions Courts under Section 438-442 BNSS (formerly Sections 397-401 CrPC) and Section 115 CPC to correct jurisdictional errors of inferior courts."),
        ("Rule of Law", "The constitutional principle that all persons and state authorities are subject to and accountable to law that is fairly applied and enforced, held to be part of the Basic Structure (*Indira Gandhi v. Raj Narain*)."),
        ("Sanhita (संहिता)", "Formal Hindi statutory term for a comprehensive, codified legal code enacted by Parliament (e.g., Bharatiya Nyaya Sanhita, Bharatiya Nagarik Suraksha Sanhita)."),
        ("Special Leave Petition (SLP)", "The extraordinary discretionary appellate jurisdiction of the Supreme Court of India under Article 136 of the Constitution to grant leave to appeal against any judgment, decree, or order of any court or tribunal."),
        ("Standard of Proof", "The quantum of evidence required to establish a fact: 'beyond reasonable doubt' in criminal proceedings versus 'preponderance of probabilities' in civil trials."),
        ("Sub Judice", "Latin for 'under a judge'; a matter that is currently under judicial consideration and therefore prohibited from public discussion that might prejudice proceedings."),
        ("Subordinate Court", "Courts below the High Court in the judicial hierarchy, including District Courts, Sessions Courts, Courts of Civil Judges, and Judicial Magistrates."),
        ("Summary Trial", "An expedited trial procedure under Sections 283 to 288 BNSS (formerly Sections 260-265 CrPC) for petty offenses where evidence is summarized rather than recorded in full."),
        ("Surety", "A person who undertakes legal and financial responsibility for another person's fulfillment of a legal obligation or appearance before a court on bail."),
        ("Test Identification Parade (TIP)", "An investigative procedure conducted under Section 54A CrPC (now Section 54 BNSS) and Section 7 BSA where witnesses identify an accused or recovered stolen property."),
        ("Tortious Liability", "Civil liability arising from the breach of a legal duty owed generally to fellow citizens, redressible by an action for unliquidated damages."),
        ("Transfer Petition", "A petition filed under Section 406 CrPC / Section 446 BNSS or Section 25 CPC before the Supreme Court seeking transfer of a case from one State to another to ensure a fair trial."),
        ("Ultra Vires", "Latin for 'beyond the powers'; an act, rule, regulation, or statutory enactment that exceeds the legal authority conferred by the Constitution or parent enabling statute, rendering it null and void."),
        ("Vakalatnama", "A written document by which an advocate is authorized to act and plead on behalf of a client in a court of law under the Advocates Act, 1961 and Court Fees Act."),
        ("Vested Interest", "An interest in property created in favor of a person without a condition precedent or where the condition is certain to happen, as defined under Section 19 of the Transfer of Property Act, 1882."),
        ("Void Ab Initio", "Latin for 'void from the beginning'; an agreement or legal order that is legally null and of no effect from its inception (e.g., an agreement with a minor under Section 11 of the Contract Act)."),
        ("Warrant Case", "A criminal case relating to an offense punishable with death, imprisonment for life, or imprisonment for a term exceeding two years under Section 2(x) BNSS (formerly Section 2(x) CrPC)."),
        ("Writ Jurisdiction", "The extraordinary equitable jurisdiction of superior courts under Articles 32 and 226 of the Constitution to issue prerogative writs (Habeas Corpus, Mandamus, Prohibition, Quo Warranto, Certiorari)."),
        ("Zero-FIR", "An FIR registered by any police station irrespective of territorial jurisdiction upon receiving information of a cognizable offense, with an obligation to immediately transfer it to the jurisdictional station."),
        ("Dying Deposition", "A statement made by a dying person recorded on oath by a Judicial Magistrate with the accused having an opportunity to cross-examine, carrying higher evidentiary weight than an unsworn dying declaration."),
        ("Estoppel", "A rule of evidence codified under Section 121 BSA (formerly Section 115 IEA) precluding a person from denying the truth of a representation they previously made that induced another to alter their position."),
        ("Fiduciary Relationship", "A legal relationship of trust and confidence between parties (e.g., trustee-beneficiary, lawyer-client, doctor-patient) imposing heightened obligations of good faith and loyalty."),
        ("In Pari Delicto", "Latin maxim meaning 'in equal fault'; legal doctrine providing that where two parties are equally at fault in an illegal contract or transaction, the court will leave them where it finds them."),
        ("Interpleader Suit", "A civil suit instituted under Section 88 and Order XXXV CPC by a person claiming no interest in the subject matter other than charges or costs, seeking adjudication between rival claimants.")
    ]
    
    lines = [
        "### 23.6 Exhaustive Indian Legal Terminology Glossary (125 Key Concepts)\n",
        "The following glossary provides authoritative statutory references and jurisprudential explanations for 125 foundational concepts in Indian public, criminal, civil, and commercial law:\n"
    ]
    
    for idx, (term, definition) in enumerate(terms, 1):
        lines.append(f"{idx:03d}. **{term}**")
        lines.append(f"     {definition}\n")
        
    return "\n".join(lines)
